pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmount, uint256 cashOutAmount) public {
        // Restrict to admissible domain: deposit > MinDeposit, cashOutAmount > 0, and cashOutAmount fits in uint underflow checks
        vm.assume(depositAmount > 1 ether);
        vm.assume(cashOutAmount > 0);
        vm.assume(cashOutAmount <= type(uint256).max - 1 ether);

        // Setup: give the caller some Ether
        address caller = address(0x1234);
        vm.deal(caller, depositAmount);

        // Deposit
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before CashOut
        uint256 balanceBefore = c.balances(caller);
        vm.assume(cashOutAmount <= balanceBefore); // ensure CashOut condition is met

        // Attempt CashOut
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("CashOut(uint256)", cashOutAmount));

        if (success) {
            uint256 balanceAfter = c.balances(caller);
            // After a successful CashOut, the caller's balance must decrease by exactly cashOutAmount
            assertTrue(balanceAfter == balanceBefore - cashOutAmount);
        }
    }
}

