pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _depositAmount, uint256 _cashOutAmount) public {
        // Restrict deposit to be > MinDeposit (1 ether) and < type(uint256).max/2 to avoid overflow
        vm.assume(_depositAmount > 1 ether);
        vm.assume(_depositAmount < (type(uint256).max / 2));
        // CashOut amount must be exactly the deposited amount (the property is that this exact amount
        // becomes available after deposit in reference, but not in buggy)
        _cashOutAmount = _depositAmount;

        address sender = address(0x1234);
        vm.deal(sender, _depositAmount);
        vm.prank(sender);
        c.Deposit{value: _depositAmount}();

        // Now try to cash out; reference should succeed, buggy should revert because balance was subtracted
        vm.prank(sender);
        try c.CashOut(_cashOutAmount) {
            // Succeeded: reference behavior
            assertTrue(true);
        } catch {
            // Reverted: buggy behavior; the assertion will fail because reference never reverts here
            assertTrue(false);
        }
    }
}

